/* ================= REAL WING HEIGHT (v79) ================= */
// wingTop() (05-rocks.js) is the top of a 0.2 m voxel: on the real wing it is +0.15 m too high on average (up to +0.23 on the spiders' walk) and it jumps in 0.2 m steps.
// WT is the real top of the wings and nacelles (the first surface of ship.glb seen from above), baked by tools/wing-table/make_wing_table.cjs: one node per 0.2 m WV column.
/*TABLE:BEGIN*/
// generated by tools/wing-table/make_wing_table.cjs from ship.glb (do not edit by hand): a node per 0.2 m column of WV, x0/z0 = centre of the first node, Y0 + Q * value metres, 0 = no wing
const WT={S:0.2,Y0:-0.7,Q:0.011,tiles:[{x0:-9.1,z0:-17.3,nx:34,nz:90,d:Uint8Array.from(atob(""),c=>c.charCodeAt(0))},{x0:2.5,z0:-17.3,nx:34,nz:90,d:Uint8Array.from(atob(""),c=>c.charCodeAt(0))}]};
/*TABLE:END*/
// real height of the wing under (x,z), or null where wingTop() is null (no wing). Bilinear between the column centres, only over the nodes that have a wing
// (so an edge column never blends in a missing neighbour); outside the table, or if every node around is unknown, wingTop() minus 0.1 (half its mean error).
function wingY(x,z){const vt=wingTop(x,z);if(vt===null)return null;
  for(const T of WT.tiles){const fx=(x-T.x0)/WT.S,fz=(z-T.z0)/WT.S;if(fx<-0.5||fz<-0.5||fx>T.nx-0.5||fz>T.nz-0.5)continue;
    const cx=Math.min(T.nx-1,Math.max(0,fx)),cz=Math.min(T.nz-1,Math.max(0,fz));let i=Math.floor(cx),j=Math.floor(cz);if(i>=T.nx-1)i=T.nx-2;if(j>=T.nz-1)j=T.nz-2;
    const u=cx-i,v=cz-j,o=j*T.nx+i,d=T.d,a=d[o],b=d[o+1],c=d[o+T.nx],e=d[o+T.nx+1];
    const wa=(1-u)*(1-v),wb=u*(1-v),wc=(1-u)*v,we=u*v;let sw=0,sh=0;
    if(a){sw+=wa;sh+=wa*a;}if(b){sw+=wb;sh+=wb*b;}if(c){sw+=wc;sh+=wc*c;}if(e){sw+=we;sh+=we*e;}
    if(sw>1e-6)return WT.Y0+WT.Q*sh/sw;break;}
  return vt-0.1;}
// unit normal of the wing surface under (x,z) (central differences of wingY over 0.5 m); straight up where there is no wing
const _wnT=new THREE.Vector3();
function wingNormal(x,z,out){const e=0.25,h0=wingY(x,z);if(h0===null)return out.set(0,1,0);
  const g=(a,b)=>{const h=wingY(a,b);return h===null?h0:h;};
  return out.set(-(g(x+e,z)-g(x-e,z))/(2*e),1,-(g(x,z+e)-g(x,z-e))/(2*e)).normalize();}
